
<div class="heading"><div><h1>Gestión de inventario</h1><small>Consulta existencias y registra entradas o salidas.</small></div><a class="primary" href="?page=productos">Agregar nueva prenda</a></div>
<div class="two-col"><div class="panel"><h3>Productos en stock</h3><div class="table-scroll"><table><thead><tr><th>Prenda</th><th>SKU</th><th>Categoría</th><th>Stock</th><th>Estado</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><div style="display:flex;align-items:center;gap:9px"><?php if($p['image_url']):?><img class="product-thumb" src="<?=e($p['image_url'])?>" alt="Prenda" loading="lazy"><?php endif;?><?=e($p['name'])?></div></td><td><?=e($p['sku'])?></td><td><?=e($p['category'])?></td><td><?=e($p['stock'])?></td><td><span class="tag <?= $p['stock']<=10?'low':'' ?>"><?= $p['stock']<=10?'Stock bajo':'Disponible' ?></span></td></tr><?php endforeach;?></tbody></table></div></div><div class="panel"><h3>Ajuste de stock</h3><form method="post" class="form-grid"><?php csrf();?><input type="hidden" name="action" value="stock"><label class="full">Producto<select name="id" required><?php foreach($products as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?> · <?=e($p['stock'])?> unidades</option><?php endforeach;?></select></label><label>Cantidad (+ entrada / - salida)<input type="number" name="delta" placeholder="Ej: 10 o -3" required></label><label>Motivo<input name="reason" maxlength="200" placeholder="Compra, ajuste, devolución..." required></label><div class="full"><button class="primary" type="submit" <?=!$products?'disabled':''?>>Guardar movimiento</button></div></form><h3 style="margin-top:28px">Últimos movimientos</h3><div class="table-scroll"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Motivo</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=e($m['name'])?></td><td class="<?= $m['quantity']<0?'red':'green' ?>"><?=e($m['quantity'])?></td><td><?=e($m['reason'])?></td></tr><?php endforeach;?></tbody></table></div></div></div>